+		for (int gi = 0; gi < fps[k]->ngroups; gi++) {
+			apply_grp_edits(&fps[k]->groups[gi], &pre_per[k][gi]);
+			free_grp(&pre_per[k][gi]);
+		}
+		free(pre_per[k]);
+	}
