+			int relc_ch = !lines_equal(eg->relc_cmd, eg->nrelc,
+						   og->relc_cmd, og->nrelc);
+			int custom_ch = !lines_equal(eg->custom_text, eg->ncustom_text,
+						     og->custom_text, og->ncustom_text);
